import java.math.BigInteger
import java.security.KeyFactory
import java.security.PrivateKey
import java.security.PublicKey
import java.security.spec.RSAPrivateKeySpec
import java.security.spec.RSAPublicKeySpec
import com.viergegroup.swmain.entities.catalogs.HostType
class HsmKeys(var hostType:HostType) {


 
    /**
     * Llave pública del servidor, para encriptar mensajes enviados y verificar firmas de mensajes
     * recibidos.
     */
      fun   getServerPublicKey():PublicKey {
        var modulus = BigInteger("", 16)
        var exponent = BigInteger("00010001", 16)
            if(hostType==HostType.OpenPayProd){
                 modulus = BigInteger("", 16)
            }
          
            val spec = RSAPublicKeySpec(modulus, exponent)
            return KeyFactory.getInstance("RSA").generatePublic(spec)
        } 

    /**
     * Llave privada del cliente, para desencriptar mensajes recibidos y firmar mensajes enviados.
     */
    fun  getClientPrivateKey(): PrivateKey{
            var modulus = BigInteger("", 16)
            var exponent = BigInteger("", 16)
            if(hostType==HostType.OpenPayProd){
                modulus = BigInteger("", 16)
                exponent = BigInteger("", 16)
 
            }
            val spec = RSAPrivateKeySpec(modulus, exponent)
            return KeyFactory.getInstance("RSA").generatePrivate(spec)
        }



}